-- Generated by scripts/build-schema.mjs.
-- Apply AFTER 20261024-remove-teacher-appeal.sql.
-- Adds the correction ledger/pins, the audited AAL2 write-back RPC, the queue
-- projection fields needed by the admin UI, and re-import protection. Existing
-- teacher/course/offering data is preserved.
BEGIN;
-- Immutable write-back ledger for accepted teacher/course/offering corrections.
-- The applicant-visible request row only records status and resolution; the
-- actual before/after values, source basis and linked request live here.
CREATE TABLE IF NOT EXISTS private.upc_data_corrections (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  request_id UUID REFERENCES public.governance_requests(id) ON DELETE SET NULL,
  actor_user_id UUID,
  actor_admin_id UUID,
  target_type TEXT NOT NULL CHECK (target_type IN ('teacher', 'course', 'offering')),
  target_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('update', 'add', 'remove')),
  before_data JSONB NOT NULL,
  after_data JSONB NOT NULL,
  source_basis TEXT NOT NULL CHECK (char_length(btrim(source_basis)) BETWEEN 10 AND 2000),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS upc_data_corrections_request_uidx
  ON private.upc_data_corrections (request_id);
CREATE INDEX IF NOT EXISTS upc_data_corrections_target_idx
  ON private.upc_data_corrections (target_type, target_id, created_at DESC);
REVOKE ALL ON private.upc_data_corrections FROM PUBLIC, anon, authenticated;

-- Fields already corrected through an accepted governance request. The import
-- RPC must not silently overwrite them; a protected field may only change via a
-- new, separately audited correction. course_offerings uses a deterministic
-- teacher|course|term key with field_name='relation' for a confirmed removal so
-- a later re-import cannot re-create the removed relation.
CREATE TABLE IF NOT EXISTS private.upc_correction_pins (
  target_table TEXT NOT NULL CHECK (target_table IN ('teachers', 'courses', 'course_offerings')),
  target_id TEXT NOT NULL,
  field_name TEXT NOT NULL,
  request_id UUID REFERENCES public.governance_requests(id) ON DELETE SET NULL,
  corrected_value JSONB,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (target_table, target_id, field_name)
);
REVOKE ALL ON private.upc_correction_pins FROM PUBLIC, anon, authenticated;

-- Account deletion removes the requester's governance request. Correction
-- records and pins are catalog-governance evidence, not applicant content, so
-- they survive with the request link nulled instead of blocking deletion.
ALTER TABLE private.upc_data_corrections ALTER COLUMN request_id DROP NOT NULL;
ALTER TABLE private.upc_data_corrections DROP CONSTRAINT IF EXISTS upc_data_corrections_request_id_fkey;
ALTER TABLE private.upc_data_corrections
  ADD CONSTRAINT upc_data_corrections_request_id_fkey
  FOREIGN KEY (request_id) REFERENCES public.governance_requests(id) ON DELETE SET NULL;
ALTER TABLE private.upc_correction_pins ALTER COLUMN request_id DROP NOT NULL;
ALTER TABLE private.upc_correction_pins DROP CONSTRAINT IF EXISTS upc_correction_pins_request_id_fkey;
ALTER TABLE private.upc_correction_pins
  ADD CONSTRAINT upc_correction_pins_request_id_fkey
  FOREIGN KEY (request_id) REFERENCES public.governance_requests(id) ON DELETE SET NULL;

DROP VIEW IF EXISTS public.admin_governance_queue;
CREATE VIEW public.admin_governance_queue AS
SELECT
  g.id, g.request_type, g.requester_kind, g.source,
  g.target_teacher_id, t.name AS target_teacher_name,
  t.title AS target_teacher_title,
  tc.code AS target_teacher_college_code,
  t.campus AS target_teacher_campus,
  g.target_review_id, g.target_course_id, c.name AS target_course_name,
  c.code AS target_course_code,
  cc.code AS target_course_college_code,
  g.target_offering_id,
  o.teacher_id AS target_offering_teacher_id,
  o.course_id AS target_offering_course_id,
  o.term_id AS target_offering_term_id,
  o.source_id AS target_offering_source_id,
  g.statement, g.evidence_summary,
  g.status, g.resolution, g.assigned_admin_id, g.external_case_ref,
  g.created_at, g.updated_at, g.resolved_at
FROM public.governance_requests g
LEFT JOIN public.teachers t ON t.id = g.target_teacher_id
LEFT JOIN public.colleges tc ON tc.id = t.college_id
LEFT JOIN public.courses c ON c.id = g.target_course_id
LEFT JOIN public.colleges cc ON cc.id = c.college_id
LEFT JOIN public.course_offerings o ON o.id = g.target_offering_id and g.target_offering_id is not null
WHERE (private.upc_admin_record()).id IS NOT NULL AND private.upc_has_aal2();
REVOKE ALL ON public.admin_governance_queue FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.admin_governance_queue TO authenticated;

CREATE OR REPLACE FUNCTION public.process_governance_request(
  p_request_id UUID, p_status TEXT, p_resolution TEXT DEFAULT NULL
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_admin public.admin_users;
  v_req public.governance_requests%ROWTYPE;
  v_status TEXT := nullif(trim(p_status), '');
  v_resolution TEXT := nullif(trim(p_resolution), '');
BEGIN
  v_admin := private.upc_require_admin();
  IF v_admin.role NOT IN ('super_admin', 'admin') THEN
    RAISE EXCEPTION '仅审核管理员可处理治理申请';
  END IF;
  IF v_status NOT IN ('triaged', 'in_review', 'accepted', 'rejected', 'completed') THEN
    RAISE EXCEPTION '无效的处理状态';
  END IF;
  IF v_status IN ('accepted', 'rejected', 'completed')
     AND (v_resolution IS NULL OR char_length(v_resolution) < 2) THEN
    RAISE EXCEPTION '接受、驳回或完成时必须填写处理结论';
  END IF;

  SELECT * INTO v_req FROM public.governance_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '申请不存在'; END IF;
  IF v_status IN ('accepted', 'completed')
     AND v_req.request_type IN ('teacher_profile_correction', 'course_offering_correction') THEN
    RAISE EXCEPTION '资料纠错必须通过 apply_governance_correction 实际写回，不能仅修改申请状态';
  END IF;
  IF v_req.status IN ('withdrawn', 'completed', 'rejected') THEN
    RAISE EXCEPTION '申请已结束，不能重复处理';
  END IF;
  IF NOT (
    (v_req.status = 'submitted' AND v_status IN ('triaged', 'in_review', 'accepted', 'rejected'))
    OR (v_req.status = 'triaged' AND v_status IN ('in_review', 'accepted', 'rejected'))
    OR (v_req.status = 'in_review' AND v_status IN ('accepted', 'rejected', 'completed'))
    OR (v_req.status = 'accepted' AND v_status = 'completed')
  ) THEN
    RAISE EXCEPTION '不允许的状态流转：% -> %', v_req.status, v_status;
  END IF;

  IF v_status IN ('accepted', 'completed') AND v_req.request_type = 'review_withdrawal' THEN
    UPDATE public.reviews
    SET is_public = false, status = 'withdrawn', withdrawn_at = now()
    WHERE id = v_req.target_review_id AND user_id = v_req.requester_user_id::text
      AND status = 'approved';
  ELSIF v_status IN ('accepted', 'completed') AND v_req.request_type = 'review_report' THEN
    UPDATE public.reviews
    SET is_public = false
    WHERE id = v_req.target_review_id AND status = 'approved';
  END IF;

  UPDATE public.governance_requests
  SET status = v_status,
      resolution = coalesce(v_resolution, resolution),
      assigned_admin_id = v_admin.id,
      updated_at = now(),
      resolved_at = CASE WHEN v_status IN ('accepted', 'rejected', 'completed') THEN now() ELSE resolved_at END
  WHERE id = p_request_id;

  INSERT INTO private.upc_governance_events
    (request_id, actor_user_id, actor_admin_id, action, from_status, to_status, note)
  VALUES (p_request_id, auth.uid(), v_admin.id, 'status_change', v_req.status, v_status, v_resolution);
  INSERT INTO private.upc_admin_audit_log
    (actor_user_id, actor_admin_id, action, target_type, target_id, reason, metadata)
  VALUES (auth.uid(), v_admin.id, 'governance_process', 'governance_request', p_request_id::text,
    v_resolution, jsonb_build_object('from', v_req.status, 'to', v_status, 'type', v_req.request_type));

  RETURN jsonb_build_object('success', true, 'status', v_status);
END $$;
REVOKE ALL ON FUNCTION public.process_governance_request(UUID, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.process_governance_request(UUID, TEXT, TEXT) TO authenticated;

-- Accepted teacher/course/offering corrections are written back here. A status
-- change alone is never treated as completion: this RPC validates the patch,
-- applies it atomically, records the before/after diff and source basis, links
-- the correction to the request and pins protected fields against re-import.
CREATE OR REPLACE FUNCTION public.apply_governance_correction(
  p_request_id UUID,
  p_patch JSONB,
  p_source_basis TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_admin public.admin_users;
  v_req public.governance_requests%ROWTYPE;
  v_basis TEXT := nullif(btrim(p_source_basis), '');
  v_patch JSONB := p_patch;
  v_obj JSONB;
  v_teacher public.teachers%ROWTYPE;
  v_course public.courses%ROWTYPE;
  v_offering public.course_offerings%ROWTYPE;
  v_before JSONB;
  v_after JSONB;
  v_target_type TEXT;
  v_target_id TEXT;
  v_action TEXT := 'update';
  v_name TEXT;
  v_title TEXT;
  v_campus TEXT;
  v_college_code TEXT;
  v_college_id UUID;
  v_course_name TEXT;
  v_course_code TEXT;
  v_course_college_id UUID;
  v_teacher_id TEXT;
  v_course_id UUID;
  v_term_id UUID;
  v_source_id TEXT;
  v_offering_id UUID;
  v_reviews INTEGER;
  v_stats INTEGER;
  v_changed TEXT[];
  v_correction_id BIGINT;
  v_pin_key TEXT;
BEGIN
  v_admin := private.upc_require_admin();
  IF v_admin.role NOT IN ('super_admin', 'admin') THEN
    RAISE EXCEPTION '仅审核管理员可写回资料纠正';
  END IF;
  IF NOT private.upc_has_aal2() THEN
    RAISE EXCEPTION '资料纠正写回需要 AAL2 强验证，请先完成 MFA';
  END IF;
  IF v_patch IS NULL OR jsonb_typeof(v_patch) <> 'object' THEN
    RAISE EXCEPTION '纠正内容必须是 JSON 对象';
  END IF;
  IF v_basis IS NULL OR char_length(v_basis) < 10 OR char_length(v_basis) > 2000 THEN
    RAISE EXCEPTION '来源依据须为 10 至 2000 个字符';
  END IF;

  SELECT * INTO v_req FROM public.governance_requests
  WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '申请不存在'; END IF;
  IF v_req.request_type NOT IN ('teacher_profile_correction', 'course_offering_correction') THEN
    RAISE EXCEPTION '该申请不是资料纠错类型';
  END IF;
  IF EXISTS (SELECT 1 FROM private.upc_data_corrections WHERE request_id = p_request_id) THEN
    RAISE EXCEPTION '该申请已写回，不能重复处理';
  END IF;
  IF v_req.status NOT IN ('submitted', 'triaged', 'in_review', 'accepted') THEN
    RAISE EXCEPTION '申请当前状态不能写回：%', v_req.status;
  END IF;
  IF v_req.request_type = 'teacher_profile_correction' THEN
    IF NOT (v_patch ? 'teacher') OR jsonb_typeof(v_patch->'teacher') <> 'object' THEN
      RAISE EXCEPTION '教师资料纠正须提供 teacher 对象';
    END IF;
    IF (v_patch - 'teacher') <> '{}'::jsonb THEN
      RAISE EXCEPTION '存在未支持的纠正字段';
    END IF;
    v_obj := v_patch->'teacher';
    IF (v_obj - ARRAY['id', 'name', 'title', 'collegeCode', 'campus']) <> '{}'::jsonb THEN
      RAISE EXCEPTION '教师纠正包含不允许的字段';
    END IF;
    IF v_req.target_teacher_id IS NULL THEN
      RAISE EXCEPTION '申请未指定教师目标';
    END IF;
    SELECT * INTO v_teacher FROM public.teachers
    WHERE id = v_req.target_teacher_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '教师目标不存在'; END IF;
    IF v_obj ? 'id' AND nullif(btrim(v_obj->>'id'), '') IS DISTINCT FROM v_teacher.id THEN
      RAISE EXCEPTION '不能改变申请指向的教师';
    END IF;

    v_before := jsonb_build_object(
      'name', v_teacher.name, 'title', v_teacher.title,
      'college_id', v_teacher.college_id, 'campus', v_teacher.campus
    );
    v_name := CASE WHEN v_obj ? 'name'
      THEN nullif(btrim(v_obj->>'name'), '') ELSE v_teacher.name END;
    v_title := CASE WHEN v_obj ? 'title'
      THEN nullif(btrim(v_obj->>'title'), '') ELSE v_teacher.title END;
    v_campus := CASE WHEN v_obj ? 'campus'
      THEN nullif(btrim(v_obj->>'campus'), '') ELSE v_teacher.campus END;
    IF v_obj ? 'collegeCode' THEN
      v_college_code := nullif(btrim(v_obj->>'collegeCode'), '');
      IF v_college_code IS NULL THEN RAISE EXCEPTION '学院编码不能为空'; END IF;
      SELECT id INTO v_college_id FROM public.colleges WHERE code = v_college_code;
      IF v_college_id IS NULL THEN RAISE EXCEPTION '学院编码不存在'; END IF;
    ELSE
      v_college_id := v_teacher.college_id;
    END IF;
    IF v_name IS NULL OR char_length(v_name) > 80 THEN
      RAISE EXCEPTION '教师姓名须为 1 至 80 个字符';
    END IF;
    IF v_title IS NOT NULL AND char_length(v_title) > 40 THEN
      RAISE EXCEPTION '职称不能超过 40 个字符';
    END IF;
    IF v_campus IS NOT NULL AND v_campus NOT IN ('唐岛湾校区', '古镇口校区', '东营科教园区') THEN
      RAISE EXCEPTION '校区不在 UPC 枚举中';
    END IF;

    v_after := jsonb_build_object(
      'name', v_name, 'title', v_title,
      'college_id', v_college_id, 'campus', v_campus
    );
    IF v_after = v_before THEN
      RAISE EXCEPTION '未检测到实际变更，不能仅修改申请状态';
    END IF;

    UPDATE public.teachers
    SET name = v_name, title = v_title, college_id = v_college_id,
        campus = v_campus, updated_at = now()
    WHERE id = v_teacher.id;

    v_changed := array_remove(ARRAY[
      CASE WHEN v_after->'name' IS DISTINCT FROM v_before->'name' THEN 'name' END,
      CASE WHEN v_after->'title' IS DISTINCT FROM v_before->'title' THEN 'title' END,
      CASE WHEN v_after->'college_id' IS DISTINCT FROM v_before->'college_id' THEN 'college_id' END,
      CASE WHEN v_after->'campus' IS DISTINCT FROM v_before->'campus' THEN 'campus' END
    ], NULL);
    IF v_after->'name' IS DISTINCT FROM v_before->'name' THEN
      INSERT INTO private.upc_correction_pins AS pin
        (target_table, target_id, field_name, request_id, corrected_value)
      VALUES ('teachers', v_teacher.id, 'name', p_request_id, v_after->'name')
      ON CONFLICT (target_table, target_id, field_name) DO UPDATE
      SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
          applied_at = now();
    END IF;
    IF v_after->'title' IS DISTINCT FROM v_before->'title' THEN
      INSERT INTO private.upc_correction_pins AS pin
        (target_table, target_id, field_name, request_id, corrected_value)
      VALUES ('teachers', v_teacher.id, 'title', p_request_id, v_after->'title')
      ON CONFLICT (target_table, target_id, field_name) DO UPDATE
      SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
          applied_at = now();
    END IF;
    IF v_after->'college_id' IS DISTINCT FROM v_before->'college_id' THEN
      INSERT INTO private.upc_correction_pins AS pin
        (target_table, target_id, field_name, request_id, corrected_value)
      VALUES ('teachers', v_teacher.id, 'college_id', p_request_id, v_after->'college_id')
      ON CONFLICT (target_table, target_id, field_name) DO UPDATE
      SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
          applied_at = now();
    END IF;
    IF v_after->'campus' IS DISTINCT FROM v_before->'campus' THEN
      INSERT INTO private.upc_correction_pins AS pin
        (target_table, target_id, field_name, request_id, corrected_value)
      VALUES ('teachers', v_teacher.id, 'campus', p_request_id, v_after->'campus')
      ON CONFLICT (target_table, target_id, field_name) DO UPDATE
      SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
          applied_at = now();
    END IF;
    v_target_type := 'teacher';
    v_target_id := v_teacher.id;

  ELSIF v_req.request_type = 'course_offering_correction' THEN
    IF (v_patch ? 'course') = (v_patch ? 'offering') THEN
      RAISE EXCEPTION '课程/授课关系纠正须且只能提供 course 或 offering 之一';
    END IF;

    IF v_patch ? 'course' THEN
      IF jsonb_typeof(v_patch->'course') <> 'object' THEN
        RAISE EXCEPTION 'course 必须是对象';
      END IF;
      v_obj := v_patch->'course';
      IF (v_obj - ARRAY['id', 'name', 'code', 'collegeCode']) <> '{}'::jsonb THEN
        RAISE EXCEPTION '课程纠正包含不允许的字段';
      END IF;
      v_course_id := v_req.target_course_id;
      IF v_course_id IS NULL AND v_req.target_offering_id IS NOT NULL THEN
        SELECT course_id INTO v_course_id FROM public.course_offerings
        WHERE id = v_req.target_offering_id;
      END IF;
      IF v_course_id IS NULL THEN RAISE EXCEPTION '申请未指定课程目标'; END IF;
      IF v_obj ? 'id' AND nullif(btrim(v_obj->>'id'), '')::uuid IS DISTINCT FROM v_course_id THEN
        RAISE EXCEPTION '不能改变申请指向的课程';
      END IF;
      SELECT * INTO v_course FROM public.courses WHERE id = v_course_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION '课程目标不存在'; END IF;

      v_before := jsonb_build_object(
        'name', v_course.name, 'code', v_course.code, 'college_id', v_course.college_id
      );
      v_course_name := CASE WHEN v_obj ? 'name'
        THEN nullif(btrim(v_obj->>'name'), '') ELSE v_course.name END;
      v_course_code := CASE WHEN v_obj ? 'code'
        THEN nullif(btrim(v_obj->>'code'), '') ELSE v_course.code END;
      IF v_obj ? 'collegeCode' THEN
        v_college_code := nullif(btrim(v_obj->>'collegeCode'), '');
        IF v_college_code IS NULL THEN RAISE EXCEPTION '课程学院编码不能为空'; END IF;
        SELECT id INTO v_course_college_id FROM public.colleges WHERE code = v_college_code;
        IF v_course_college_id IS NULL THEN RAISE EXCEPTION '课程学院编码不存在'; END IF;
      ELSE
        v_course_college_id := v_course.college_id;
      END IF;
      IF v_course_name IS NULL OR char_length(v_course_name) > 160 THEN
        RAISE EXCEPTION '课程名称须为 1 至 160 个字符';
      END IF;
      IF v_course_code IS NOT NULL AND char_length(v_course_code) > 80 THEN
        RAISE EXCEPTION '课程编码不能超过 80 个字符';
      END IF;
      IF v_course_code IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.courses WHERE code = v_course_code AND id <> v_course.id
      ) THEN
        RAISE EXCEPTION '课程编码已被其他课程占用';
      END IF;
      IF v_course_code IS NULL AND EXISTS (
        SELECT 1 FROM public.courses
        WHERE name = v_course_name AND college_id = v_course_college_id
          AND code IS NULL AND id <> v_course.id
      ) THEN
        RAISE EXCEPTION '同名无编码课程已存在，不能产生歧义';
      END IF;

      v_after := jsonb_build_object(
        'name', v_course_name, 'code', v_course_code, 'college_id', v_course_college_id
      );
      IF v_after = v_before THEN
        RAISE EXCEPTION '未检测到实际变更，不能仅修改申请状态';
      END IF;

      UPDATE public.courses
      SET name = v_course_name, code = v_course_code, college_id = v_course_college_id
      WHERE id = v_course.id;

      v_changed := array_remove(ARRAY[
        CASE WHEN v_after->'name' IS DISTINCT FROM v_before->'name' THEN 'name' END,
        CASE WHEN v_after->'code' IS DISTINCT FROM v_before->'code' THEN 'code' END,
        CASE WHEN v_after->'college_id' IS DISTINCT FROM v_before->'college_id' THEN 'college_id' END
      ], NULL);
      IF v_after->'name' IS DISTINCT FROM v_before->'name' THEN
        INSERT INTO private.upc_correction_pins AS pin
          (target_table, target_id, field_name, request_id, corrected_value)
        VALUES ('courses', v_course.id::text, 'name', p_request_id, v_after->'name')
        ON CONFLICT (target_table, target_id, field_name) DO UPDATE
        SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
            applied_at = now();
      END IF;
      IF v_after->'code' IS DISTINCT FROM v_before->'code' THEN
        INSERT INTO private.upc_correction_pins AS pin
          (target_table, target_id, field_name, request_id, corrected_value)
        VALUES ('courses', v_course.id::text, 'code', p_request_id, v_after->'code')
        ON CONFLICT (target_table, target_id, field_name) DO UPDATE
        SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
            applied_at = now();
      END IF;
      IF v_after->'college_id' IS DISTINCT FROM v_before->'college_id' THEN
        INSERT INTO private.upc_correction_pins AS pin
          (target_table, target_id, field_name, request_id, corrected_value)
        VALUES ('courses', v_course.id::text, 'college_id', p_request_id, v_after->'college_id')
        ON CONFLICT (target_table, target_id, field_name) DO UPDATE
        SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
            applied_at = now();
      END IF;
      v_target_type := 'course';
      v_target_id := v_course.id::text;

    ELSE
      IF jsonb_typeof(v_patch->'offering') <> 'object' THEN
        RAISE EXCEPTION 'offering 必须是对象';
      END IF;
      v_obj := v_patch->'offering';
      IF (v_obj - ARRAY['action', 'offeringId', 'teacherId', 'courseId', 'termId', 'sourceId'])
         <> '{}'::jsonb THEN
        RAISE EXCEPTION '授课关系纠正包含不允许的字段';
      END IF;
      v_action := lower(coalesce(nullif(btrim(v_obj->>'action'), ''), ''));
      IF v_action NOT IN ('add', 'remove') THEN
        RAISE EXCEPTION '授课关系动作只支持 add 或 remove';
      END IF;

      IF v_action = 'remove' THEN
        v_offering_id := nullif(btrim(v_obj->>'offeringId'), '')::uuid;
        IF v_offering_id IS NULL THEN v_offering_id := v_req.target_offering_id; END IF;
        IF v_offering_id IS NOT NULL THEN
          SELECT * INTO v_offering FROM public.course_offerings
          WHERE id = v_offering_id FOR UPDATE;
        ELSE
          v_teacher_id := nullif(btrim(v_obj->>'teacherId'), '');
          v_course_id := nullif(btrim(v_obj->>'courseId'), '')::uuid;
          v_term_id := nullif(btrim(v_obj->>'termId'), '')::uuid;
          IF v_teacher_id IS NULL OR v_course_id IS NULL OR v_term_id IS NULL THEN
            RAISE EXCEPTION '删除授课关系须提供 offeringId 或完整的 teacherId/courseId/termId';
          END IF;
          SELECT * INTO v_offering FROM public.course_offerings
          WHERE teacher_id = v_teacher_id AND course_id = v_course_id AND term_id = v_term_id
          FOR UPDATE;
        END IF;
        IF NOT FOUND THEN RAISE EXCEPTION '授课关系不存在'; END IF;
        IF v_obj ? 'teacherId'
           AND nullif(btrim(v_obj->>'teacherId'), '') IS DISTINCT FROM v_offering.teacher_id THEN
          RAISE EXCEPTION '提供的教师与授课关系目标不一致';
        END IF;
        IF v_obj ? 'courseId'
           AND nullif(btrim(v_obj->>'courseId'), '')::uuid IS DISTINCT FROM v_offering.course_id THEN
          RAISE EXCEPTION '提供的课程与授课关系目标不一致';
        END IF;
        IF v_obj ? 'termId'
           AND nullif(btrim(v_obj->>'termId'), '')::uuid IS DISTINCT FROM v_offering.term_id THEN
          RAISE EXCEPTION '提供的学期与授课关系目标不一致';
        END IF;

        SELECT count(*)::int INTO v_reviews
        FROM public.reviews
        WHERE teacher_id = v_offering.teacher_id
          AND course_id = v_offering.course_id
          AND term_id = v_offering.term_id;
        SELECT count(*)::int INTO v_stats
        FROM public.offering_rating_stats
        WHERE teacher_id = v_offering.teacher_id
          AND course_id = v_offering.course_id
          AND term_id = v_offering.term_id;
        IF v_reviews > 0 OR v_stats > 0 THEN
          RAISE EXCEPTION '授课关系仍关联 % 条评价和 % 条统计，拒绝自动删除或转移；请先处理评价引用',
            v_reviews, v_stats;
        END IF;

        v_before := to_jsonb(v_offering);
        DELETE FROM public.course_offerings WHERE id = v_offering.id;
        v_after := '{}'::jsonb;
        v_target_type := 'offering';
        v_target_id := v_offering.id::text;
        v_changed := ARRAY['relation'];
        v_pin_key := v_offering.teacher_id || '|' || v_offering.course_id::text
          || '|' || v_offering.term_id::text;
        INSERT INTO private.upc_correction_pins AS pin
          (target_table, target_id, field_name, request_id, corrected_value)
        VALUES ('course_offerings', v_pin_key, 'relation', p_request_id,
          jsonb_build_object('action', 'removed', 'offeringId', v_offering.id))
        ON CONFLICT (target_table, target_id, field_name) DO UPDATE
        SET request_id = EXCLUDED.request_id, corrected_value = EXCLUDED.corrected_value,
            applied_at = now();
      ELSE
        v_teacher_id := nullif(btrim(v_obj->>'teacherId'), '');
        v_course_id := nullif(btrim(v_obj->>'courseId'), '')::uuid;
        v_term_id := nullif(btrim(v_obj->>'termId'), '')::uuid;
        v_source_id := nullif(btrim(v_obj->>'sourceId'), '');
        IF v_obj ? 'offeringId' THEN
          RAISE EXCEPTION '新增授课关系不能指定 offeringId';
        END IF;
        IF v_teacher_id IS NULL OR v_course_id IS NULL OR v_term_id IS NULL THEN
          RAISE EXCEPTION '新增授课关系须提供 teacherId/courseId/termId';
        END IF;
        IF v_source_id IS NOT NULL AND char_length(v_source_id) > 120 THEN
          RAISE EXCEPTION '授课关系来源标识不能超过 120 个字符';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.teachers WHERE id = v_teacher_id) THEN
          RAISE EXCEPTION '教师不存在';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.courses WHERE id = v_course_id) THEN
          RAISE EXCEPTION '课程不存在';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.terms WHERE id = v_term_id) THEN
          RAISE EXCEPTION '学期不存在';
        END IF;
        IF EXISTS (
          SELECT 1 FROM public.course_offerings
          WHERE teacher_id = v_teacher_id AND course_id = v_course_id AND term_id = v_term_id
        ) THEN
          RAISE EXCEPTION '授课关系已存在，无需新增';
        END IF;

        v_before := '{}'::jsonb;
        INSERT INTO public.course_offerings (teacher_id, course_id, term_id, source_id)
        VALUES (v_teacher_id, v_course_id, v_term_id, v_source_id)
        RETURNING * INTO v_offering;
        v_after := to_jsonb(v_offering);
        v_target_type := 'offering';
        v_target_id := v_offering.id::text;
        v_changed := ARRAY['relation'];
        v_pin_key := v_teacher_id || '|' || v_course_id::text || '|' || v_term_id::text;
        DELETE FROM private.upc_correction_pins
        WHERE target_table = 'course_offerings' AND target_id = v_pin_key
          AND field_name = 'relation';
      END IF;
    END IF;
  END IF;

  INSERT INTO private.upc_data_corrections
    (request_id, actor_user_id, actor_admin_id, target_type, target_id, action,
     before_data, after_data, source_basis)
  VALUES (p_request_id, auth.uid(), v_admin.id, v_target_type, v_target_id, v_action,
    v_before, v_after, v_basis)
  RETURNING id INTO v_correction_id;

  UPDATE public.governance_requests
  SET status = 'completed',
      resolution = coalesce(resolution, '资料纠正已写回并完成'),
      assigned_admin_id = v_admin.id,
      updated_at = now(),
      resolved_at = now()
  WHERE id = p_request_id;

  INSERT INTO private.upc_governance_events
    (request_id, actor_user_id, actor_admin_id, action, from_status, to_status, note)
  VALUES (p_request_id, auth.uid(), v_admin.id, 'correction_applied',
    v_req.status, 'completed', v_basis);

  INSERT INTO private.upc_admin_audit_log
    (actor_user_id, actor_admin_id, action, target_type, target_id, reason, metadata)
  VALUES (auth.uid(), v_admin.id, 'governance_correction_apply', v_target_type,
    v_target_id, v_basis, jsonb_build_object(
      'request_id', p_request_id,
      'correction_id', v_correction_id,
      'action', v_action,
      'changed_fields', to_jsonb(v_changed)
    ));

  RETURN jsonb_build_object(
    'success', true, 'correction_id', v_correction_id, 'request_id', p_request_id,
    'status', 'completed', 'target_type', v_target_type, 'target_id', v_target_id,
    'action', v_action, 'changed_fields', to_jsonb(v_changed),
    'before', v_before, 'after', v_after
  );
END $$;
REVOKE ALL ON FUNCTION public.apply_governance_correction(UUID, JSONB, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.apply_governance_correction(UUID, JSONB, TEXT) TO authenticated;

-- Controlled recovery after an administrator loses a TOTP device. This is not a
-- public recovery endpoint: only the service role may execute it, and it never
-- changes the administrator's role, active flag or password. The operator must
-- verify identity out of band, delete the old factors through the Auth Admin API,
-- then call this function to revoke sessions and append an audit record.
CREATE OR REPLACE FUNCTION public.record_admin_mfa_recovery(
  p_user_id UUID,
  p_operator TEXT,
  p_reason TEXT,
  p_factor_ids TEXT[]
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_admin public.admin_users%ROWTYPE;
  v_sessions INTEGER;
  v_operator TEXT := nullif(btrim(p_operator), '');
  v_reason TEXT := nullif(btrim(p_reason), '');
BEGIN
  IF coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'role', '')
     <> 'service_role' THEN
    RAISE EXCEPTION '仅受控后台服务可执行管理员 MFA 恢复';
  END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION '目标管理员 user_id 必填'; END IF;
  IF v_operator IS NULL OR char_length(v_operator) < 2 OR char_length(v_operator) > 120 THEN
    RAISE EXCEPTION '操作人标识须为 2 至 120 个字符';
  END IF;
  IF v_reason IS NULL OR char_length(v_reason) < 20 OR char_length(v_reason) > 1000 THEN
    RAISE EXCEPTION '恢复原因须为 20 至 1000 个字符';
  END IF;
  IF p_factor_ids IS NULL OR cardinality(p_factor_ids) = 0
     OR cardinality(p_factor_ids) > 20 THEN
    RAISE EXCEPTION '须提供 1 至 20 个已删除的 MFA factor 标识';
  END IF;

  SELECT * INTO v_admin FROM public.admin_users WHERE user_id = p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION '目标不是已登记管理员'; END IF;

  DELETE FROM auth.sessions WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_sessions = ROW_COUNT;

  INSERT INTO private.upc_admin_audit_log
    (actor_user_id, actor_admin_id, action, target_type, target_id, reason, metadata)
  VALUES (NULL, NULL, 'admin_mfa_recovery', 'admin_user', p_user_id::text, v_reason,
    jsonb_build_object(
      'operator', v_operator,
      'factor_ids', to_jsonb(p_factor_ids),
      'sessions_revoked', v_sessions,
      'admin_role', v_admin.role,
      'admin_active', v_admin.is_active
    ));

  RETURN jsonb_build_object(
    'success', true, 'sessions_revoked', v_sessions,
    'role', v_admin.role, 'active', v_admin.is_active
  );
END $$;
REVOKE ALL ON FUNCTION public.record_admin_mfa_recovery(UUID, TEXT, TEXT, TEXT[])
  FROM PUBLIC, anon, authenticated;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    GRANT EXECUTE ON FUNCTION public.record_admin_mfa_recovery(UUID, TEXT, TEXT, TEXT[])
      TO service_role;
  END IF;
END $$;

-- Atomic UPC data import. Executed with the service role only.
--
-- Contract:
--   * teachers are keyed by sourceId and stored as 'upc:<sourceId>';
--   * same-name teachers are never merged;
--   * courses are keyed by code when present, otherwise by (name, college);
--   * offerings require a term and are unique by teacher × course × term;
--   * a dry run executes the same writes in a subtransaction, then rolls back;
--     batch conflicts therefore fail the preflight exactly as the real import;
--   * any bad row aborts the whole call, so a partial batch is never committed.

CREATE OR REPLACE FUNCTION private.upc_import_dataset_apply(
  p_payload JSONB,
  p_checksum TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_term JSONB;
  v_teachers JSONB;
  v_teacher JSONB;
  v_course JSONB;
  v_dataset TEXT;
  v_source TEXT;
  v_term_code TEXT;
  v_term_name TEXT;
  v_term_current BOOLEAN;
  v_term_id UUID;
  v_existing_term_name TEXT;
  v_existing_term_current BOOLEAN;
  v_term_inserted INT := 0;
  v_term_updated INT := 0;
  v_term_skipped INT := 0;
  v_teacher_inserted INT := 0;
  v_teacher_updated INT := 0;
  v_teacher_skipped INT := 0;
  v_teacher_protected INT := 0;
  v_course_inserted INT := 0;
  v_course_updated INT := 0;
  v_course_skipped INT := 0;
  v_course_protected INT := 0;
  v_offering_inserted INT := 0;
  v_offering_skipped INT := 0;
  v_offering_protected INT := 0;
  v_source_id TEXT;
  v_teacher_id TEXT;
  v_name TEXT;
  v_title TEXT;
  v_campus TEXT;
  v_college_code TEXT;
  v_college_id UUID;
  v_current_name TEXT;
  v_current_title TEXT;
  v_current_campus TEXT;
  v_current_college_id UUID;
  v_pin_name BOOLEAN;
  v_pin_title BOOLEAN;
  v_pin_campus BOOLEAN;
  v_pin_college BOOLEAN;
  v_pin_course_name BOOLEAN;
  v_pin_course_code BOOLEAN;
  v_pin_course_college BOOLEAN;
  v_pinned_code_course_id UUID;
  v_course_code TEXT;
  v_course_name TEXT;
  v_course_college_code TEXT;
  v_course_college_id UUID;
  v_course_id UUID;
  v_existing_course_name TEXT;
  v_existing_course_college UUID;
  v_same BOOLEAN;
  v_rows INT;
  v_summary JSONB;
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION '导入数据必须是 JSON 对象';
  END IF;
  IF coalesce(p_payload->>'schemaVersion', '') !~ '^[0-9]+$'
     OR (p_payload->>'schemaVersion')::int <> 1 THEN
    RAISE EXCEPTION '不支持的导入数据版本，只接受 schemaVersion=1';
  END IF;
  IF p_checksum IS NULL OR p_checksum !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION '缺少有效的 SHA-256 校验值';
  END IF;

  v_dataset := nullif(trim(p_payload->>'dataset'), '');
  v_source := nullif(trim(p_payload->>'source'), '');
  IF v_dataset IS NULL OR char_length(v_dataset) > 200 THEN
    RAISE EXCEPTION 'dataset 必填且不超过 200 字符';
  END IF;
  IF v_source IS NULL OR char_length(v_source) > 500 THEN
    RAISE EXCEPTION 'source 必填且不超过 500 字符（记录可核对的来源）';
  END IF;

  v_teachers := p_payload->'teachers';
  IF v_teachers IS NULL OR jsonb_typeof(v_teachers) <> 'array' OR jsonb_array_length(v_teachers) = 0 THEN
    RAISE EXCEPTION 'teachers 必须是非空数组';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_teachers) e
    GROUP BY nullif(trim(e->>'sourceId'), '')
    HAVING count(*) > 1 OR nullif(trim(e->>'sourceId'), '') IS NULL
  ) THEN
    RAISE EXCEPTION 'teachers 中存在空白或重复的 sourceId';
  END IF;

  v_term := p_payload->'term';
  IF v_term IS NOT NULL AND jsonb_typeof(v_term) = 'null' THEN
    v_term := NULL;
  END IF;
  IF v_term IS NOT NULL THEN
    IF jsonb_typeof(v_term) <> 'object' THEN
      RAISE EXCEPTION 'term 必须是对象或 null';
    END IF;
    v_term_code := nullif(trim(v_term->>'code'), '');
    v_term_name := nullif(trim(v_term->>'name'), '');
    IF v_term_code IS NULL OR v_term_name IS NULL THEN
      RAISE EXCEPTION 'term.code 与 term.name 均必填';
    END IF;
    v_term_current := coalesce((v_term->>'isCurrent')::boolean, false);

    SELECT id, year_term, is_current INTO v_term_id, v_existing_term_name, v_existing_term_current
    FROM public.terms WHERE code = v_term_code;

    IF v_term_id IS NULL THEN
      INSERT INTO public.terms (code, year_term, is_current)
      VALUES (v_term_code, v_term_name, false)
      RETURNING id INTO v_term_id;
      v_term_inserted := v_term_inserted + 1;
    ELSIF v_existing_term_name = v_term_name AND v_existing_term_current = v_term_current THEN
      v_term_skipped := v_term_skipped + 1;
    ELSE
      UPDATE public.terms
      SET year_term = v_term_name
      WHERE id = v_term_id;
      v_term_updated := v_term_updated + 1;
    END IF;

    IF v_term_current THEN
      UPDATE public.terms SET is_current = false
      WHERE is_current AND id IS DISTINCT FROM v_term_id;
      UPDATE public.terms SET is_current = true WHERE id = v_term_id;
    END IF;
  END IF;

  FOR v_teacher IN SELECT value FROM jsonb_array_elements(v_teachers) LOOP
    v_source_id := nullif(trim(v_teacher->>'sourceId'), '');
    v_name := nullif(trim(v_teacher->>'name'), '');
    v_title := nullif(trim(v_teacher->>'title'), '');
    v_campus := nullif(trim(v_teacher->>'campus'), '');
    v_college_code := nullif(trim(v_teacher->>'collegeCode'), '');

    IF v_source_id IS NULL OR char_length(v_source_id) > 120
       OR position('/' IN v_source_id) > 0 OR position(chr(92) IN v_source_id) > 0 THEN
      RAISE EXCEPTION '教师 sourceId 必填、不超过 120 字符且不能包含斜杠';
    END IF;
    IF v_name IS NULL OR char_length(v_name) > 80 THEN
      RAISE EXCEPTION '教师 % 的姓名必填且不超过 80 字符', v_source_id;
    END IF;
    IF v_title IS NOT NULL AND char_length(v_title) > 40 THEN
      RAISE EXCEPTION '教师 % 的职称超过 40 字符', v_source_id;
    END IF;
    IF v_campus IS NOT NULL AND v_campus NOT IN ('唐岛湾校区', '古镇口校区', '东营科教园区') THEN
      RAISE EXCEPTION '教师 % 的校区 % 不在 UPC 校区枚举中', v_source_id, v_campus;
    END IF;
    IF v_college_code IS NULL THEN
      RAISE EXCEPTION '教师 % 缺少 collegeCode', v_source_id;
    END IF;

    SELECT id INTO v_college_id FROM public.colleges WHERE code = v_college_code;
    IF v_college_id IS NULL THEN
      RAISE EXCEPTION '教师 % 的学院编码 % 不存在，请先导入学院字典', v_source_id, v_college_code;
    END IF;

    v_teacher_id := 'upc:' || v_source_id;
    IF NOT EXISTS (SELECT 1 FROM public.teachers WHERE id = v_teacher_id) THEN
      INSERT INTO public.teachers (id, source_id, name, title, college_id, campus, rating_version)
      VALUES (v_teacher_id, v_source_id, v_name, v_title, v_college_id, v_campus, 2);
      v_teacher_inserted := v_teacher_inserted + 1;
    ELSE
      SELECT name, title, college_id, campus
      INTO v_current_name, v_current_title, v_current_college_id, v_current_campus
      FROM public.teachers WHERE id = v_teacher_id;

      -- Confirmed governance corrections are authoritative. A later batch may
      -- leave protected fields untouched but must never silently undo them.
      SELECT
        coalesce(bool_or(field_name = 'name'), false),
        coalesce(bool_or(field_name = 'title'), false),
        coalesce(bool_or(field_name = 'campus'), false),
        coalesce(bool_or(field_name = 'college_id'), false)
      INTO v_pin_name, v_pin_title, v_pin_campus, v_pin_college
      FROM private.upc_correction_pins
      WHERE target_table = 'teachers' AND target_id = v_teacher_id;

      IF v_pin_name AND v_name IS DISTINCT FROM v_current_name THEN
        v_name := v_current_name;
        v_teacher_protected := v_teacher_protected + 1;
      END IF;
      IF v_pin_title AND v_title IS DISTINCT FROM v_current_title THEN
        v_title := v_current_title;
        v_teacher_protected := v_teacher_protected + 1;
      END IF;
      IF v_pin_campus AND v_campus IS DISTINCT FROM v_current_campus THEN
        v_campus := v_current_campus;
        v_teacher_protected := v_teacher_protected + 1;
      END IF;
      IF v_pin_college THEN
        IF v_college_id IS DISTINCT FROM v_current_college_id THEN
          v_teacher_protected := v_teacher_protected + 1;
        END IF;
        v_college_id := v_current_college_id;
      END IF;

      SELECT (name = v_name
              AND title IS NOT DISTINCT FROM v_title
              AND college_id = v_college_id
              AND campus IS NOT DISTINCT FROM v_campus)
      INTO v_same
      FROM public.teachers WHERE id = v_teacher_id;

      IF v_same THEN
        v_teacher_skipped := v_teacher_skipped + 1;
      ELSE
        UPDATE public.teachers
        SET name = v_name, title = v_title, college_id = v_college_id, campus = v_campus
        WHERE id = v_teacher_id;
        v_teacher_updated := v_teacher_updated + 1;
      END IF;
    END IF;

    IF v_teacher ? 'courses' AND jsonb_typeof(v_teacher->'courses') <> 'array' THEN
      RAISE EXCEPTION '教师 % 的 courses 必须是数组', v_source_id;
    END IF;
    IF jsonb_array_length(coalesce(v_teacher->'courses', '[]'::jsonb)) > 0
       AND v_term IS NULL THEN
      RAISE EXCEPTION '教师 % 有课程但整批未提供 term', v_source_id;
    END IF;

    FOR v_course IN SELECT value FROM jsonb_array_elements(coalesce(v_teacher->'courses', '[]'::jsonb)) LOOP
      v_course_code := nullif(trim(v_course->>'code'), '');
      v_course_name := nullif(trim(v_course->>'name'), '');
      IF v_course_name IS NULL OR char_length(v_course_name) > 160 THEN
        RAISE EXCEPTION '教师 % 的课程名称必填且不超过 160 字符', v_source_id;
      END IF;
      IF v_course_code IS NOT NULL AND char_length(v_course_code) > 80 THEN
        RAISE EXCEPTION '教师 % 的课程代码超过 80 字符', v_source_id;
      END IF;

      -- The offering unit is separate from the teacher's HR college. It defaults
      -- to the teacher's college when not supplied.
      v_course_college_code := nullif(trim(v_course->>'collegeCode'), '');
      IF v_course_college_code IS NULL THEN
        v_course_college_id := v_college_id;
      ELSE
        SELECT id INTO v_course_college_id
        FROM public.colleges WHERE code = v_course_college_code;
        IF v_course_college_id IS NULL THEN
          RAISE EXCEPTION '教师 % 的课程 % 指定学院编码 % 不存在', v_source_id, v_course_name, v_course_college_code;
        END IF;
      END IF;

      v_course_id := NULL;
      v_existing_course_name := NULL;
      v_existing_course_college := NULL;

      IF v_course_code IS NOT NULL THEN
        SELECT id, name, college_id
        INTO v_course_id, v_existing_course_name, v_existing_course_college
        FROM public.courses WHERE code = v_course_code;

        IF v_course_id IS NOT NULL THEN
          SELECT
            coalesce(bool_or(field_name = 'name'), false),
            coalesce(bool_or(field_name = 'code'), false),
            coalesce(bool_or(field_name = 'college_id'), false)
          INTO v_pin_course_name, v_pin_course_code, v_pin_course_college
          FROM private.upc_correction_pins
          WHERE target_table = 'courses' AND target_id = v_course_id::text;

          IF v_existing_course_name IS DISTINCT FROM v_course_name THEN
            IF v_pin_course_name THEN
              v_course_name := v_existing_course_name;
              v_course_protected := v_course_protected + 1;
            ELSE
              RAISE EXCEPTION '课程代码 % 已存在名称 %，与本次名称 % 冲突',
                v_course_code, v_existing_course_name, v_course_name;
            END IF;
          END IF;
          IF v_existing_course_college IS DISTINCT FROM v_course_college_id THEN
            IF v_pin_course_college THEN
              v_course_college_id := v_existing_course_college;
              v_course_protected := v_course_protected + 1;
            ELSE
              RAISE EXCEPTION '课程代码 % 已归属其他学院，不能静默改归属', v_course_code;
            END IF;
          END IF;
          v_course_skipped := v_course_skipped + 1;
        ELSE
          -- A governance correction may have pinned this course's code. If the
          -- incoming source still uses the old code, fail closed instead of
          -- creating a duplicate course under the corrected catalog.
          SELECT c.id INTO v_pinned_code_course_id
          FROM private.upc_correction_pins p
          JOIN public.courses c ON c.id::text = p.target_id
          WHERE p.target_table = 'courses' AND p.field_name = 'code'
            AND c.name = v_course_name AND c.college_id = v_course_college_id
            AND p.corrected_value IS DISTINCT FROM to_jsonb(v_course_code)
          LIMIT 1;
          IF v_pinned_code_course_id IS NOT NULL THEN
            RAISE EXCEPTION '课程 % 的编码已由治理纠正固定，本次导入编码 % 与纠正结果冲突，请人工核对',
              v_course_name, v_course_code;
          END IF;

          -- Adopt a single uncoded course with the same name/college. If a coded
          -- same-name course also exists, the uncoded record is ambiguous.
          SELECT id INTO v_course_id
          FROM public.courses
          WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NULL
          LIMIT 1;

          IF v_course_id IS NOT NULL THEN
            IF EXISTS (
              SELECT 1 FROM public.courses
              WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NOT NULL
            ) THEN
              RAISE EXCEPTION '课程 % 同时存在有编码和无编码记录，无法安全采用编码 %',
                v_course_name, v_course_code;
            END IF;
            UPDATE public.courses SET code = v_course_code WHERE id = v_course_id;
            v_course_updated := v_course_updated + 1;
          ELSE
            INSERT INTO public.courses (code, name, college_id)
            VALUES (v_course_code, v_course_name, v_course_college_id)
            RETURNING id INTO v_course_id;
            v_course_inserted := v_course_inserted + 1;
          END IF;
        END IF;
      ELSE
        -- Without a code, only an uncoded row can be matched. A coded same-name
        -- row makes the identity ambiguous and must not be duplicated.
        SELECT id INTO v_course_id
        FROM public.courses
        WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NULL
        LIMIT 1;

        IF v_course_id IS NOT NULL THEN
          v_course_skipped := v_course_skipped + 1;
        ELSE
          IF EXISTS (
            SELECT 1 FROM public.courses
            WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NOT NULL
          ) THEN
            RAISE EXCEPTION '课程 % 已有编码记录，无编码导入会产生歧义', v_course_name;
          END IF;
          INSERT INTO public.courses (code, name, college_id)
          VALUES (NULL, v_course_name, v_course_college_id)
          RETURNING id INTO v_course_id;
          v_course_inserted := v_course_inserted + 1;
        END IF;
      END IF;

      IF v_term_id IS NULL THEN
        RAISE EXCEPTION '教师 % 有课程但 term 未能建立', v_source_id;
      END IF;
      -- A confirmed removal is recorded as a relation pin. Re-import must not
      -- silently resurrect a relation that governance decided to delete.
      IF EXISTS (
        SELECT 1 FROM private.upc_correction_pins
        WHERE target_table = 'course_offerings'
          AND target_id = v_teacher_id || '|' || v_course_id::text || '|' || v_term_id::text
          AND field_name = 'relation'
          AND corrected_value->>'action' = 'removed'
      ) THEN
        v_offering_protected := v_offering_protected + 1;
      ELSE
        INSERT INTO public.course_offerings (teacher_id, course_id, term_id)
        VALUES (v_teacher_id, v_course_id, v_term_id)
        ON CONFLICT (teacher_id, course_id, term_id) DO NOTHING;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows = 1 THEN
          v_offering_inserted := v_offering_inserted + 1;
        ELSE
          v_offering_skipped := v_offering_skipped + 1;
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  v_summary := jsonb_build_object(
    'success', true,
    'dryRun', false,
    'dataset', v_dataset,
    'source', v_source,
    'checksum', p_checksum,
    'term', jsonb_build_object(
      'inserted', v_term_inserted,
      'updated', v_term_updated,
      'skipped', v_term_skipped
    ),
    'teachers', jsonb_build_object(
      'inserted', v_teacher_inserted,
      'updated', v_teacher_updated,
      'skipped', v_teacher_skipped,
      'protectedFields', v_teacher_protected
    ),
    'courses', jsonb_build_object(
      'inserted', v_course_inserted,
      'updated', v_course_updated,
      'skipped', v_course_skipped,
      'protectedFields', v_course_protected
    ),
    'offerings', jsonb_build_object(
      'inserted', v_offering_inserted,
      'skipped', v_offering_skipped,
      'protectedRelations', v_offering_protected
    )
  );

  INSERT INTO public.import_batches (dataset, source, checksum, summary)
  VALUES (v_dataset, v_source, p_checksum, v_summary);

  RETURN v_summary;
END $$;
REVOKE ALL ON FUNCTION private.upc_import_dataset_apply(JSONB, TEXT)
  FROM PUBLIC, anon, authenticated;

-- Dry run uses the same apply function in a subtransaction, then raises a private
-- sentinel to force a rollback. Other errors propagate unchanged, so a preflight
-- cannot report success for a batch that the real import would reject.
CREATE OR REPLACE FUNCTION public.import_upc_dataset(
  p_payload JSONB,
  p_checksum TEXT,
  p_dry_run BOOLEAN DEFAULT false
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_summary JSONB;
  v_detail TEXT;
BEGIN
  IF p_dry_run IS NOT TRUE THEN
    RETURN private.upc_import_dataset_apply(p_payload, p_checksum);
  END IF;

  BEGIN
    v_summary := private.upc_import_dataset_apply(p_payload, p_checksum);
    RAISE EXCEPTION USING ERRCODE = 'UP001', MESSAGE = 'UPC_DRY_RUN',
      DETAIL = (v_summary || jsonb_build_object('dryRun', true))::text;
  EXCEPTION WHEN SQLSTATE 'UP001' THEN
    GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
    RETURN v_detail::jsonb;
  END;
END $$;

REVOKE ALL ON FUNCTION public.import_upc_dataset(JSONB, TEXT, BOOLEAN)
  FROM PUBLIC, anon, authenticated;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    GRANT EXECUTE ON FUNCTION public.import_upc_dataset(JSONB, TEXT, BOOLEAN) TO service_role;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


NOTIFY pgrst, 'reload schema';
COMMIT;
